effect.shader:
void main(){
  vec2 uv = acScreenNorm;
  float ar = acScreenSize.x / max(acScreenSize.y, 1.0);
  vec2 p = (uv - vec2(centerX, centerY)) * vec2(ar, 1.0);
  float r = length(p);
  vec2 dir = p / (r + 1e-5);
  float w = sin(r * frequency - acTime * speed * 6.2831853) * amplitude * mixAmt;
  uv += dir * w;
  gl_FragColor = texture2DCv(inputImg.texture, uv);
}
